function orderProductLink(product) {
  if (!product) return '';
  const slug = String(product.slug || '').trim();
  const id = String(product.id || '').trim();
  const sourceUrl = String(product.sourceUrl || product.supplierUrl || product.purchaseUrl || '').trim();
  return String(ORDER_PRODUCT_LINKS[slug] || ORDER_PRODUCT_LINKS[id] || sourceUrl || '').trim();
}

module.exports = { ORDER_PRODUCT_LINKS, orderProductLink };
